   OR (r->'peer_months'->0->>'avg_amount')::numeric<>104.70 THEN RAISE EXCEPTION 'Personal-finance restriction incorrect'; END IF;
 DELETE FROM public."HomePermissionOverride" WHERE home_id=h;
