 IF (public.get_home_bill_comparison(h,a,'USD')->'peer_months'->0->>'household_count')::integer<>9 THEN RAISE EXCEPTION 'Stale moved Home'; END IF;
 UPDATE public."Home" SET location=ST_SetSRID(ST_MakePoint(0,0),4326) WHERE id=pg_temp.bc_id(110);
