 IF (public.get_home_bill_comparison(h,a,'USD')->'peer_months'->0->>'household_count')::integer<>9 THEN RAISE EXCEPTION 'Stale deleted contribution'; END IF;
 INSERT INTO public."HomeBill" SELECT (jsonb_populate_record(NULL::public."HomeBill",value)).* FROM bc_original WHERE value->>'id'=pg_temp.bc_id(210)::text;
 IF (public.get_home_bill_comparison(h,a,'USD')->'peer_months'->0->>'avg_amount')::numeric<>104.70 THEN RAISE EXCEPTION 'Restored contribution not read'; END IF;
